module.exports = function(RED) {
    const SessionManager = require('kumva-insights/utils/session-manager');
    const helpers = require('kumva-insights/utils/helpers');

    let sessionManager = null;

    async function getSessionManager() {
        if (!sessionManager) {
            sessionManager = new SessionManager();
            await sessionManager.initialize();
        }
        return sessionManager;
    }

    // Main Africa's Talking IVR Webhook. add flowId to the url.
    RED.httpNode.post('/kumva/ivr/callback', async (req, res) => {
        try {
            const payload = req.body;
            const atSessionId = payload.sessionId || payload.SessionId;

            console.log(`[Kumva Webhook] Received callback - Session: ${atSessionId}, DTMF: ${payload.dtmfDigits || payload.Digits}`);

            if (!atSessionId) {
                return res.status(400).json({ success: false, error: "No sessionId" });
            }

            const sm = await getSessionManager();
            const sessionResult = await sm.getSession(atSessionId);

            if (!sessionResult.exists) {
                console.warn(`[Webhook] Session not found: ${atSessionId}`);
                return res.status(200).send('<Response><Hangup/></Response>');
            }

            const session = sessionResult.data;

            // Emit event so waiting nodes can pick it up
            RED.events.emit('kumva:response', {
                atSessionId: atSessionId,
                dtmfDigits: payload.dtmfDigits || payload.Digits,
                callerNumber: payload.callerNumber || payload.CallerNumber,
                flowId: session.flowId,
                nodeId: session.currentNodeId,
                rawPayload: payload
            });

            // Basic VoiceXML response
            res.set('Content-Type', 'text/xml');
            res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
    <GetDigits timeout="30" finishOnKey="#" callbackUrl="${process.env.BASE_URL || 'http://localhost:1880'}/kumva/ivr/callback"/>
</Response>`);

        } catch (err) {
            console.error("[Kumva Webhook Error]", err);
            res.status(500).send('<Response><Hangup/></Response>');
        }
    });

    console.log("Kumva IVR Webhook registered at /kumva/ivr/callback");
};